-- ── Verify counts ─────────────────────────────────────────────
SELECT 'Farmers'   AS type, COUNT(*)::TEXT AS count FROM users    WHERE role='farmer';
SELECT 'Customers' AS type, COUNT(*)::TEXT AS count FROM users    WHERE role='consumer';
SELECT 'Products'  AS type, COUNT(*)::TEXT AS count FROM products WHERE is_active=TRUE;
SELECT 'Orders'    AS type, COUNT(*)::TEXT AS count FROM orders;
SELECT 'Revenue ₹' AS type, SUM(total_price)::TEXT AS count FROM orders WHERE id LIKE 'o1000001%';
